/**
 * RealWorld error envelope: `{ "errors": { "<field>": ["<message>", ...] } }`.
 */
export type ErrorBody = Record<string, string[]>;

export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly errors: ErrorBody,
  ) {
    super(`API error ${status}`);
  }
}

export const unprocessable = (errors: ErrorBody) => new ApiError(422, errors);
export const notFound = (resource: string) => new ApiError(404, { [resource]: ['not found'] });
export const forbidden = (resource: string) => new ApiError(403, { [resource]: ['forbidden'] });
export const tokenMissing = () => new ApiError(401, { token: ['is missing'] });
export const tokenInvalid = () => new ApiError(401, { token: ['is invalid'] });
export const conflict = (field: string) => new ApiError(409, { [field]: ['has already been taken'] });
export const invalidCredentials = () => new ApiError(401, { credentials: ['invalid'] });

