import { randomBytes } from 'node:crypto';

function slugifyTitle(title: string): string {
  const base = title
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return base.length > 0 ? base.slice(0, 200) : 'article';
}

/**
 * Builds a URL slug from a title. Duplicate titles are allowed by the spec, so
 * collisions are resolved with a random suffix via `isTaken`.
 */
export async function buildUniqueSlug(
  title: string,
  isTaken: (slug: string) => Promise<boolean>,
): Promise<string> {
  const base = slugifyTitle(title);
  if (!(await isTaken(base))) return base;

  for (;;) {
    const candidate = `${base}-${randomBytes(4).toString('hex')}`;
    if (!(await isTaken(candidate))) return candidate;
  }
}

