import { signToken } from './token.js';

export interface UserRecord {
  id: number;
  username: string;
  email: string;
  bio: string | null;
  image: string | null;
}

export interface ArticleRecord {
  id: number;
  slug: string;
  title: string;
  description: string;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: UserRecord;
  tags: { tag: { name: string } }[];
  favorites: { userId: number }[];
  _count: { favorites: number };
}

export interface CommentRecord {
  id: number;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: UserRecord;
}

/** RealWorld timestamps are ISO-8601 with millisecond precision. */
const iso = (date: Date) => date.toISOString();

export function toUserResponse(user: UserRecord, token?: string) {
  return {
    user: {
      email: user.email,
      token: token ?? signToken({ id: user.id, username: user.username }),
      username: user.username,
      bio: user.bio,
      image: user.image,
    },
  };
}

export function toProfile(user: UserRecord, following: boolean) {
  return {
    username: user.username,
    bio: user.bio,
    image: user.image,
    following,
  };
}

export function toProfileResponse(user: UserRecord, following: boolean) {
  return { profile: toProfile(user, following) };
}

interface ArticleViewOptions {
  /** Id of the requesting user, or null for anonymous requests. */
  viewerId: number | null;
  /** Author ids the viewer follows; used to fill `author.following`. */
  followedAuthorIds: Set<number>;
  /** List responses omit `body` entirely; single-article responses include it. */
  includeBody: boolean;
}

export function toArticle(article: ArticleRecord, options: ArticleViewOptions) {
  const view: Record<string, unknown> = {
    slug: article.slug,
    title: article.title,
    description: article.description,
    tagList: article.tags.map((link) => link.tag.name).sort(),
    createdAt: iso(article.createdAt),
    updatedAt: iso(article.updatedAt),
    favorited:
      options.viewerId !== null &&
      article.favorites.some((favorite) => favorite.userId === options.viewerId),
    favoritesCount: article._count.favorites,
    author: toProfile(article.author, options.followedAuthorIds.has(article.author.id)),
  };

  if (options.includeBody) {
    // Keep the spec's field order: body sits between description and tagList.
    return {
      slug: view.slug,
      title: view.title,
      description: view.description,
      body: article.body,
      tagList: view.tagList,
      createdAt: view.createdAt,
      updatedAt: view.updatedAt,
      favorited: view.favorited,
      favoritesCount: view.favoritesCount,
      author: view.author,
    };
  }
  return view;
}

export function toComment(
  comment: CommentRecord,
  options: { following: boolean },
) {
  return {
    id: comment.id,
    createdAt: iso(comment.createdAt),
    updatedAt: iso(comment.updatedAt),
    body: comment.body,
    author: toProfile(comment.author, options.following),
  };
}

