import type { FastifyRequest } from 'fastify';
import { tokenInvalid, tokenMissing } from './errors.js';
import { prisma } from './prisma.js';
import { verifyToken } from './token.js';
import type { UserRecord } from './serializers.js';

/** RealWorld uses `Authorization: Token <jwt>`; `Bearer` is accepted too. */
function extractToken(request: FastifyRequest): string | null {
  const header = request.headers.authorization;
  if (!header) return null;
  const match = /^(?:Token|Bearer)\s+(.+)$/i.exec(header.trim());
  return match ? match[1].trim() : null;
}

async function loadUser(request: FastifyRequest): Promise<UserRecord | null> {
  const raw = extractToken(request);
  if (!raw) return null;
  const payload = verifyToken(raw);
  if (!payload) throw tokenInvalid();

  const user = await prisma.user.findUnique({ where: { id: payload.id } });
  if (!user) throw tokenInvalid();
  return user;
}

/** Resolves the authenticated user or throws 401. */
export async function requireUser(request: FastifyRequest): Promise<UserRecord> {
  const user = await loadUser(request);
  if (!user) throw tokenMissing();
  return user;
}

/** Resolves the authenticated user, or null when no credentials were sent. */
export async function optionalUser(request: FastifyRequest): Promise<UserRecord | null> {
  return loadUser(request);
}

