import bcrypt from 'bcryptjs';
import type { FastifyInstance } from 'fastify';
import { requireUser } from '../lib/auth.js';
import { conflict, invalidCredentials } from '../lib/errors.js';
import { prisma } from '../lib/prisma.js';
import { toUserResponse } from '../lib/serializers.js';
import {
  ErrorCollector,
  envelope,
  optionalNullableString,
  optionalRequiredString,
  validatePassword,
} from '../lib/validation.js';

const BCRYPT_ROUNDS = 10;

async function assertUsernameAvailable(username: string, exceptId?: number): Promise<void> {
  const existing = await prisma.user.findUnique({ where: { username } });
  if (existing && existing.id !== exceptId) throw conflict('username');
}

async function assertEmailAvailable(email: string, exceptId?: number): Promise<void> {
  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing && existing.id !== exceptId) throw conflict('email');
}

export async function userRoutes(app: FastifyInstance): Promise<void> {
  // POST /api/users — registration
  app.post('/api/users', async (request, reply) => {
    const fields = envelope(request.body, 'user');
    const collector = new ErrorCollector();
    collector.requirePresent('username', fields.username);
    collector.requirePresent('email', fields.email);
    collector.requirePresent('password', fields.password);
    collector.throwIfAny();

    const username = (fields.username as string).trim();
    const email = (fields.email as string).trim();

    await assertUsernameAvailable(username);
    await assertEmailAvailable(email);

    const user = await prisma.user.create({
      data: {
        username,
        email,
        passwordHash: await bcrypt.hash(fields.password as string, BCRYPT_ROUNDS),
      },
    });

    return reply.code(201).send(toUserResponse(user));
  });

  // POST /api/users/login
  app.post('/api/users/login', async (request, reply) => {
    const fields = envelope(request.body, 'user');
    const collector = new ErrorCollector();
    collector.requirePresent('email', fields.email);
    collector.requirePresent('password', fields.password);
    collector.throwIfAny();

    const user = await prisma.user.findUnique({
      where: { email: (fields.email as string).trim() },
    });
    if (!user) throw invalidCredentials();

    const matches = await bcrypt.compare(fields.password as string, user.passwordHash);
    if (!matches) throw invalidCredentials();

    return reply.send(toUserResponse(user));
  });

  // GET /api/user — current user
  app.get('/api/user', async (request, reply) => {
    const user = await requireUser(request);
    return reply.send(toUserResponse(user));
  });

  // PUT /api/user — update current user
  app.put('/api/user', async (request, reply) => {
    const current = await requireUser(request);
    const fields = envelope(request.body, 'user');
    const collector = new ErrorCollector();

    const username = optionalRequiredString(collector, fields, 'username');
    const email = optionalRequiredString(collector, fields, 'email');
    const bio = optionalNullableString(collector, fields, 'bio');
    const image = optionalNullableString(collector, fields, 'image');
    if ('password' in fields) validatePassword(collector, fields.password);
    collector.throwIfAny();

    if (username !== undefined) await assertUsernameAvailable(username, current.id);
    if (email !== undefined) await assertEmailAvailable(email, current.id);

    const user = await prisma.user.update({
      where: { id: current.id },
      data: {
        ...(username !== undefined ? { username } : {}),
        ...(email !== undefined ? { email } : {}),
        ...(bio !== undefined ? { bio } : {}),
        ...(image !== undefined ? { image } : {}),
        ...('password' in fields
          ? { passwordHash: await bcrypt.hash(fields.password as string, BCRYPT_ROUNDS) }
          : {}),
        updatedAt: new Date(),
      },
    });

    return reply.send(toUserResponse(user));
  });
}

