import type { FastifyInstance } from 'fastify';
import { optionalUser, requireUser } from '../lib/auth.js';
import { notFound } from '../lib/errors.js';
import { prisma } from '../lib/prisma.js';
import { toProfileResponse } from '../lib/serializers.js';

interface UsernameParams {
  username: string;
}

async function findProfileOrThrow(username: string) {
  const user = await prisma.user.findUnique({ where: { username } });
  if (!user) throw notFound('profile');
  return user;
}

async function isFollowing(followerId: number, followingId: number): Promise<boolean> {
  const edge = await prisma.follow.findUnique({
    where: { followerId_followingId: { followerId, followingId } },
  });
  return edge !== null;
}

export async function profileRoutes(app: FastifyInstance): Promise<void> {
  // GET /api/profiles/:username
  app.get<{ Params: UsernameParams }>('/api/profiles/:username', async (request, reply) => {
