import { notFound } from './errors.js';
import { prisma } from './prisma.js';
import { toArticle, type ArticleRecord } from './serializers.js';

/** Relations every article response needs (author, tags, favorite state). */
export const ARTICLE_INCLUDE = {
  author: true,
  tags: { include: { tag: true } },
  favorites: { select: { userId: true } },
  _count: { select: { favorites: true } },
} as const;

export async function findArticleOrThrow(slug: string) {
  const article = await prisma.article.findUnique({
    where: { slug },
    include: ARTICLE_INCLUDE,
  });
  if (!article) throw notFound('article');
  return article;
}

/** Subset of `authorIds` that `viewerId` follows. */
export async function followedAuthorIds(
  viewerId: number | null,
  authorIds: number[],
): Promise<Set<number>> {
  if (viewerId === null || authorIds.length === 0) return new Set();
  const edges = await prisma.follow.findMany({
    where: { followerId: viewerId, followingId: { in: [...new Set(authorIds)] } },
    select: { followingId: true },
  });
  return new Set(edges.map((edge) => edge.followingId));
}

export async function renderArticle(article: ArticleRecord, viewerId: number | null) {
  const following = await followedAuthorIds(viewerId, [article.author.id]);
  return { article: toArticle(article, { viewerId, followedAuthorIds: following, includeBody: true }) };
}

export async function renderArticleList(articles: ArticleRecord[], viewerId: number | null, total: number) {
  const following = await followedAuthorIds(
    viewerId,
    articles.map((article) => article.author.id),
  );
  return {
    articles: articles.map((article) =>
      toArticle(article, { viewerId, followedAuthorIds: following, includeBody: false }),
    ),
    articlesCount: total,
  };
}

/**
 * SQLite stores millisecond precision, so two updates inside the same
 * millisecond would produce an identical `updatedAt`. The spec requires the
 * timestamp to change on every update, so step forward when needed.
 */
export function nextUpdatedAt(previous: Date): Date {
  return new Date(Math.max(Date.now(), previous.getTime() + 1));
}

