import type { Prisma } from '@prisma/client';
import type { FastifyInstance } from 'fastify';
import {
  ARTICLE_INCLUDE,
  findArticleOrThrow,
  nextUpdatedAt,
  renderArticle,
  renderArticleList,
} from '../lib/articleQuery.js';
import { optionalUser, requireUser } from '../lib/auth.js';
import { forbidden } from '../lib/errors.js';
import { prisma } from '../lib/prisma.js';
import { buildUniqueSlug } from '../lib/slug.js';
import {
  ErrorCollector,
  envelope,
  optionalRequiredString,
  parseNonNegativeInt,
} from '../lib/validation.js';

interface SlugParams {
  slug: string;
}

interface ListQuery {
  tag?: string;
  author?: string;
  favorited?: string;
  limit?: string;
  offset?: string;
}

/**
 * Validates `tagList`: absent means "leave unchanged", `null` is rejected, and
 * anything else must be an array of non-blank strings.
 */
function readTagList(
  collector: ErrorCollector,
  fields: Record<string, unknown>,
): string[] | undefined {
  if (!('tagList' in fields)) return undefined;
  const value = fields.tagList;
  if (!Array.isArray(value) || value.some((tag) => typeof tag !== 'string')) {
    collector.add('tagList', 'is invalid');
    return undefined;
  }
  const names = (value as string[]).map((tag) => tag.trim()).filter((tag) => tag.length > 0);
  return [...new Set(names)];
}

/** Replaces an article's tags, creating any tag rows that do not exist yet. */
async function syncTags(articleId: number, names: string[]): Promise<void> {
  await prisma.articleTag.deleteMany({ where: { articleId } });
  for (const name of names) {
    const tag = await prisma.tag.upsert({ where: { name }, create: { name }, update: {} });
    await prisma.articleTag.create({ data: { articleId, tagId: tag.id } });
  }
}

export async function articleRoutes(app: FastifyInstance): Promise<void> {
  // GET /api/articles/feed — must be registered before the `:slug` route.
  app.get<{ Querystring: ListQuery }>('/api/articles/feed', async (request, reply) => {
    const viewer = await requireUser(request);
    const limit = parseNonNegativeInt(request.query.limit, 20);
    const offset = parseNonNegativeInt(request.query.offset, 0);

    const edges = await prisma.follow.findMany({
      where: { followerId: viewer.id },
      select: { followingId: true },
    });
    const authorIds = edges.map((edge) => edge.followingId);
    const where: Prisma.ArticleWhereInput = { authorId: { in: authorIds } };

    const [total, articles] = await Promise.all([
      prisma.article.count({ where }),
      prisma.article.findMany({
        where,
        include: ARTICLE_INCLUDE,
        orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
        take: limit,
        skip: offset,
      }),
    ]);

    return reply.send(await renderArticleList(articles, viewer.id, total));
  });

  // GET /api/articles — list articles with optional filters
  app.get<{ Querystring: ListQuery }>('/api/articles', async (request, reply) => {
    const viewer = await optionalUser(request);
    const { tag, author, favorited } = request.query;
    const limit = parseNonNegativeInt(request.query.limit, 20);
    const offset = parseNonNegativeInt(request.query.offset, 0);

    const where: Prisma.ArticleWhereInput = {
      ...(tag ? { tags: { some: { tag: { name: tag } } } } : {}),
      ...(author ? { author: { username: author } } : {}),
      ...(favorited ? { favorites: { some: { user: { username: favorited } } } } : {}),
    };

    const [total, articles] = await Promise.all([
      prisma.article.count({ where }),
      prisma.article.findMany({
        where,
        include: ARTICLE_INCLUDE,
        orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
        take: limit,
        skip: offset,
      }),
    ]);

    return reply.send(await renderArticleList(articles, viewer?.id ?? null, total));
  });

  // POST /api/articles
  app.post('/api/articles', async (request, reply) => {
    const author = await requireUser(request);
    const fields = envelope(request.body, 'article');
    const collector = new ErrorCollector();
    collector.requirePresent('title', fields.title);
    collector.requirePresent('description', fields.description);
    collector.requirePresent('body', fields.body);
    const tagList = readTagList(collector, fields);
    collector.throwIfAny();

    const title = (fields.title as string).trim();
    const slug = await buildUniqueSlug(title, async (candidate) => {
      const existing = await prisma.article.findUnique({ where: { slug: candidate } });
      return existing !== null;
    });

    const created = await prisma.article.create({
      data: {
        slug,
        title,
        description: (fields.description as string).trim(),
        body: fields.body as string,
        authorId: author.id,
      },
    });
    if (tagList && tagList.length > 0) await syncTags(created.id, tagList);

    const article = await findArticleOrThrow(slug);
    return reply.code(201).send(await renderArticle(article, author.id));
  });

  // GET /api/articles/:slug
  app.get<{ Params: SlugParams }>('/api/articles/:slug', async (request, reply) => {
    const viewer = await optionalUser(request);
    const article = await findArticleOrThrow(request.params.slug);
    return reply.send(await renderArticle(article, viewer?.id ?? null));
  });

  // PUT /api/articles/:slug
  app.put<{ Params: SlugParams }>('/api/articles/:slug', async (request, reply) => {
    const viewer = await requireUser(request);
    const existing = await findArticleOrThrow(request.params.slug);
    if (existing.authorId !== viewer.id) throw forbidden('article');

    const fields = envelope(request.body, 'article');
    const collector = new ErrorCollector();
    const title = optionalRequiredString(collector, fields, 'title');
    const description = optionalRequiredString(collector, fields, 'description');
    const body = optionalRequiredString(collector, fields, 'body');
    const tagList = readTagList(collector, fields);
    collector.throwIfAny();

    // Changing the title re-derives the slug, as in the reference implementation.
    const slug =
      title !== undefined && title !== existing.title
        ? await buildUniqueSlug(title, async (candidate) => {
            const found = await prisma.article.findUnique({ where: { slug: candidate } });
            return found !== null && found.id !== existing.id;
          })
        : existing.slug;

    await prisma.article.update({
      where: { id: existing.id },
      data: {
        slug,
        ...(title !== undefined ? { title } : {}),
        ...(description !== undefined ? { description } : {}),
        ...(body !== undefined ? { body } : {}),
        updatedAt: nextUpdatedAt(existing.updatedAt),
      },
    });
    if (tagList !== undefined) await syncTags(existing.id, tagList);

    const article = await findArticleOrThrow(slug);
    return reply.send(await renderArticle(article, viewer.id));
  });

  // DELETE /api/articles/:slug
  app.delete<{ Params: SlugParams }>('/api/articles/:slug', async (request, reply) => {
    const viewer = await requireUser(request);
    const article = await findArticleOrThrow(request.params.slug);
    if (article.authorId !== viewer.id) throw forbidden('article');

    await prisma.article.delete({ where: { id: article.id } });
    return reply.code(204).send();
  });

  // POST /api/articles/:slug/favorite
  app.post<{ Params: SlugParams }>('/api/articles/:slug/favorite', async (request, reply) => {
    const viewer = await requireUser(request);
    const article = await findArticleOrThrow(request.params.slug);

    await prisma.favorite.upsert({
      where: { userId_articleId: { userId: viewer.id, articleId: article.id } },
      create: { userId: viewer.id, articleId: article.id },
      update: {},
    });

    return reply.send(await renderArticle(await findArticleOrThrow(article.slug), viewer.id));
  });

  // DELETE /api/articles/:slug/favorite
  app.delete<{ Params: SlugParams }>('/api/articles/:slug/favorite', async (request, reply) => {
    const viewer = await requireUser(request);
    const article = await findArticleOrThrow(request.params.slug);

    await prisma.favorite.deleteMany({ where: { userId: viewer.id, articleId: article.id } });

    return reply.send(await renderArticle(await findArticleOrThrow(article.slug), viewer.id));
  });
}

