import type { FastifyInstance } from 'fastify';
import { findArticleOrThrow, followedAuthorIds } from '../lib/articleQuery.js';
import { optionalUser, requireUser } from '../lib/auth.js';
import { forbidden, notFound } from '../lib/errors.js';
import { prisma } from '../lib/prisma.js';
import { toComment } from '../lib/serializers.js';
import { ErrorCollector, envelope } from '../lib/validation.js';

interface SlugParams {
  slug: string;
}

interface CommentParams extends SlugParams {
  id: string;
}

export async function commentRoutes(app: FastifyInstance): Promise<void> {
  // POST /api/articles/:slug/comments
  app.post<{ Params: SlugParams }>('/api/articles/:slug/comments', async (request, reply) => {
    const viewer = await requireUser(request);
    const article = await findArticleOrThrow(request.params.slug);

    const fields = envelope(request.body, 'comment');
    const collector = new ErrorCollector();
    collector.requirePresent('body', fields.body);
    collector.throwIfAny();

    const comment = await prisma.comment.create({
