        toComment(comment, { following: following.has(comment.authorId) }),
      ),
    });
  });

  // DELETE /api/articles/:slug/comments/:id
  app.delete<{ Params: CommentParams }>(
    '/api/articles/:slug/comments/:id',
    async (request, reply) => {
      const viewer = await requireUser(request);
      const article = await findArticleOrThrow(request.params.slug);

